# fxtrail, gunconnect, hudmeter, levelname, meshstep, music, peerclamp, powerboost, sendguard (with ReadCombatSwitch's own rules: qc_default_off,
# qc_source_absent, qc_no_kind_warn), sensorwd, shieldgamma, sound_symbol_guard, texture_quest2, voipdrop, wallfire).
